def check(expr):
    toks=expr.split()
    people=toks[0::2]; ops=toks[1::2]
    parent_of={}; female=set(); male=set(); sib=[]
    for a,op,b in zip(people,ops,people[1:]):
        if op=='+': parent_of.setdefault(b,set()).add(a); female.add(a)
        elif op=='-': parent_of.setdefault(b,set()).add(a); male.add(a)
        elif op=='$': parent_of.setdefault(a,set()).add(b); male.add(a)
        elif op=='%': female.add(a); sib.append((a,b))
        elif op=='/': female.add(a); male.add(b)
        elif op=='=': male.add(a); sib.append((a,b))
    return 'K' in parent_of.get('A',set()) and 'A' in female
